const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=1800,H=1200,keys=new Set();
const player={x:170,y:600,r:13,speed:178,stamina:100,hp:3,light:true,relay:0,battery:false,invuln:0};
const relays=[{x:440,y:244},{x:923,y:936},{x:1434,y:380}];
const exit={x:1644,y:1002};
const monster={x:1230,y:558,r:19,alert:0,phase:0};
const camera={x:0,y:0};
let started=false,ended=false,won=false,elapsed=0,last=0,toast='',toastTime=0,noiseSeed=76421;
const obstacles=[
 {x:270,y:390,w:150,h:104},{x:625,y:155,w:180,h:115},{x:715,y:690,w:160,h:130},
 {x:1110,y:225,w:155,h:120},{x:1250,y:740,w:180,h:125},{x:345,y:825,w:130,h:110},
 {x:1515,y:615,w:135,h:105}
];
function rand(){noiseSeed=(noiseSeed*1664525+1013904223)>>>0;return noiseSeed/4294967296}
const trees=[];
for(let i=0;i<190;i++){let x=rand()*W,y=rand()*H;if(Math.abs(y-600)<65||Math.abs(x-900)<50)continue;let near=obstacles.some(o=>x>o.x-28&&x<o.x+o.w+28&&y>o.y-28&&y<o.y+o.h+28);if(!near)trees.push({x,y,r:15+rand()*12,shade:Math.floor(rand()*3)})}
function showToast(t){toast=t;toastTime=2.2}
function reset(){player.x=170;player.y=600;player.stamina=100;player.hp=3;player.light=true;player.relay=0;player.battery=false;player.invuln=0;monster.x=1230;monster.y=558;monster.alert=0;elapsed=0;ended=false;won=false;started=true;document.getElementById('overlay').classList.add('hidden');showToast('RADIO CHECK: FIND THE RELAYS');updateUI()}
function updateUI(){document.getElementById('relayCount').textContent=String(player.relay).padStart(2,'0')+' / 03';document.getElementById('health').textContent=player.hp?Array(player.hp).fill('♥').join(' '):'—';document.getElementById('stamina').style.width=player.stamina+'%';document.getElementById('lightState').textContent=player.light?'ON':'OFF';for(let i=1;i<=3;i++)document.getElementById('slot'+i).classList.toggle('found',player.relay>=i);document.getElementById('slot4').classList.toggle('found',player.battery);document.getElementById('timer').textContent=fmt(elapsed);if(player.relay===3){document.getElementById('missionTitle').textContent='Reach the gate';document.getElementById('missionCopy').textContent='All relays are online. The gate is pulsing to the east — get there before the creature does.'}else{document.getElementById('missionTitle').textContent='Recover the relays';document.getElementById('missionCopy').textContent='The emergency transmitter needs 3 signal relays. Keep your flashlight on the tree line.'}}
function fmt(t){let n=Math.floor(t);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function pressed(k){return keys.has(k.toLowerCase())||keys.has(k)}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function moveBlocked(x,y){if(x<20||y<20||x>W-20||y>H-20)return true;for(const o of obstacles)if(x>o.x-14&&x<o.x+o.w+14&&y>o.y-14&&y<o.y+o.h+14)return true;for(const t of trees)if(Math.hypot(x-t.x,y-t.y)<t.r*.72+11)return true;return false}

function update(dt){if(!started||ended)return;elapsed+=dt;player.invuln=Math.max(0,player.invuln-dt);if(toastTime>0)toastTime-=dt;
 let dx=(pressed('d')||pressed('ArrowRight')?1:0)-(pressed('a')||pressed('ArrowLeft')?1:0),dy=(pressed('s')||pressed('ArrowDown')?1:0)-(pressed('w')||pressed('ArrowUp')?1:0);let len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len}const running=(pressed('shift')||pressed('Shift'))&&player.stamina>2&&len>0;let speed=player.speed*(running?1.55:1);if(running)player.stamina=Math.max(0,player.stamina-34*dt);else player.stamina=Math.min(100,player.stamina+22*dt);
 let nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(!moveBlocked(nx,player.y))player.x=nx;if(!moveBlocked(player.x,ny))player.y=ny;
 relays.forEach((r,i)=>{if(!r.found&&dist(player,r)<31){r.found=true;player.relay++;showToast('SIGNAL RELAY '+player.relay+' / 3 RECOVERED');updateUI()}});
 if(!player.battery&&dist(player,{x:775,y:494})<30){player.battery=true;player.stamina=Math.min(100,player.stamina+35);showToast('FOUND: SPARE BATTERY');updateUI()}
 let md=dist(player,monster);if(md<430)monster.alert=Math.min(1,monster.alert+dt*.75);else monster.alert=Math.max(0,monster.alert-dt*.17);
 if(monster.alert>0){let a=Math.atan2(player.y-monster.y,player.x-monster.x),ms=85+monster.alert*48;if(player.light&&md<215)ms*=.32;monster.x+=Math.cos(a)*ms*dt;monster.y+=Math.sin(a)*ms*dt}
 monster.phase+=dt*5;
 if(md<34&&player.invuln<=0){player.hp--;player.invuln=1.6;let a=Math.atan2(player.y-monster.y,player.x-monster.x);player.x+=Math.cos(a)*48;player.y+=Math.sin(a)*48;monster.alert=.3;showToast(player.hp?'IT FOUND YOU — KEEP MOVING':'THE WOODS GO QUIET');updateUI();if(!player.hp)finish(false)}
 if(player.relay===3&&dist(player,exit)<39)finish(true);
 camera.x=Math.max(0,Math.min(W-canvas.width,player.x-canvas.width/2));camera.y=Math.max(0,Math.min(H-canvas.height,player.y-canvas.height/2));
}
function finish(victory){ended=true;won=victory;const ov=document.getElementById('overlay');ov.classList.remove('hidden');ov.querySelector('.intro').innerHTML=victory?'<div class="eyebrow">CASE FILE CLOSED · 12:14 AM</div><h1 class="title">YOU<br><span>MADE</span><br>IT.</h1><p>The transmitter is alive. The gate sealed behind you — for now. Hawkins will sleep another night.</p><button class="start-btn" id="start">Play again&nbsp; →</button><div class="message">Survived in '+fmt(elapsed)+'</div>':'<div class="eyebrow">SIGNAL LOST · CASE FILE 011-86</div><h1 class="title">THE<br><span>WOODS</span><br>KEEP YOU.</h1><p>The transmitter is still quiet. The thing in the trees is not. Try another route, and keep moving.</p><button class="start-btn" id="start">Try again&nbsp; →</button><div class="message">You lasted '+fmt(elapsed)+'</div>';document.getElementById('start').onclick=reset}
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function draw(){const cw=canvas.width,ch=canvas.height;ctx.clearRect(0,0,cw,ch);ctx.save();ctx.translate(-camera.x,-camera.y);
 // Moss-dark woodland floor and the worn county road.
 ctx.fillStyle='#18221d';ctx.fillRect(camera.x,camera.y,cw,ch);
 for(let i=0;i<190;i++){let x=(i*173+49)%W,y=(i*311+83)%H;ctx.fillStyle=i%3?'#1b2720':'#202820';ctx.fillRect(x,y,2,2)}
 ctx.fillStyle='#33352e';ctx.fillRect(0,548,W,104);ctx.fillStyle='#3b3b32';ctx.fillRect(0,553,W,94);ctx.fillStyle='#77705b';ctx.globalAlpha=.22;for(let x=0;x<W;x+=76)ctx.fillRect(x,599,38,2);ctx.globalAlpha=1;
 // Side trail connecting the transmitter to the gate.
 ctx.fillStyle='#302f28';ctx.beginPath();ctx.moveTo(871,0);ctx.lineTo(928,0);ctx.lineTo(947,538);ctx.lineTo(900,600);ctx.lineTo(855,564);ctx.closePath();ctx.fill();ctx.fillRect(899,600,48,600);
 // Buildings and their warm, unreliable windows.
 obstacles.forEach((o,i)=>{ctx.fillStyle='#101412';ctx.fillRect(o.x+8,o.y+10,o.w,o.h);ctx.fillStyle='#3a3930';ctx.fillRect(o.x,o.y,o.w,o.h);ctx.fillStyle='#514c3c';ctx.fillRect(o.x-4,o.y-8,o.w+8,15);ctx.fillStyle='#272923';ctx.fillRect(o.x+10,o.y+12,o.w-20,o.h-22);ctx.fillStyle=i%2?'#b78449':'#d19d54';ctx.globalAlpha=.5;ctx.fillRect(o.x+24,o.y+28,20,19);ctx.fillRect(o.x+o.w-45,o.y+28,20,19);ctx.globalAlpha=1;ctx.fillStyle='#3c3324';ctx.fillRect(o.x+o.w/2-13,o.y+o.h-37,26,37);ctx.strokeStyle='#68604b';ctx.lineWidth=2;ctx.strokeRect(o.x+10,o.y+12,o.w-20,o.h-22)});
 // Old fence rails near the path.
 ctx.strokeStyle='#625d4c';ctx.lineWidth=3;for(let x=45;x<1740;x+=100){if(x>850&&x<970)continue;let y=x<850?530:664;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+55,y);ctx.moveTo(x+4,y-15);ctx.lineTo(x+4,y+11);ctx.moveTo(x+51,y-15);ctx.lineTo(x+51,y+11);ctx.stroke()}
 trees.forEach(t=>drawTree(t));
 relays.forEach((r,i)=>{if(!r.found)drawRelay(r,i)});
 drawBattery();drawGate();drawMonster();drawPlayer();
 ctx.restore();drawDarkness();drawScreenUI();requestAnimationFrame(frame)}
function drawTree(t){let x=t.x,y=t.y;ctx.fillStyle='#0c1311';ctx.beginPath();ctx.ellipse(x+3,y+11,t.r*.94,t.r*.43,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#291e1a';ctx.fillRect(x-4,y-5,8,20);let colors=['#26352b','#2d392d','#35402f'];ctx.fillStyle=colors[t.shade];ctx.beginPath();ctx.arc(x,y-5,t.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#43503a';ctx.globalAlpha=.55;ctx.beginPath();ctx.arc(x-t.r*.28,y-t.r*.3,t.r*.43,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
function drawRelay(r,i){let p=(Math.sin(elapsed*3+i)*.5+.5);ctx.save();ctx.translate(r.x,r.y);ctx.globalAlpha=.2+p*.14;ctx.fillStyle='#f0d17f';ctx.beginPath();ctx.arc(0,0,24+p*7,0,7);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#c9a860';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,11,0,7);ctx.stroke();ctx.fillStyle='#e7d18f';ctx.fillRect(-6,-6,12,12);ctx.fillStyle='#fff0bb';ctx.fillRect(-2,-2,4,4);ctx.restore()}
function drawBattery(){let x=775,y=494;ctx.save();ctx.translate(x,y);ctx.shadowBlur=12;ctx.shadowColor='#9ed18c';ctx.fillStyle='#8eb77b';ctx.fillRect(-9,-5,18,11);ctx.fillRect(-3,-8,6,3);ctx.fillStyle='#253026';ctx.fillRect(-5,-2,10,5);ctx.restore()}

