function drawGate(){let x=exit.x,y=exit.y,p=.5+.5*Math.sin(elapsed*2.7);ctx.save();ctx.translate(x,y);ctx.globalAlpha=.16+p*.12;ctx.fillStyle='#dd4c46';ctx.beginPath();ctx.arc(0,0,66+p*10,0,7);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#a63b37';ctx.lineWidth=7;ctx.beginPath();ctx.ellipse(0,0,29,43,0,0,7);ctx.stroke();ctx.strokeStyle='#d6584e';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,23,37,0,0,7);ctx.stroke();ctx.fillStyle='#080b0c';ctx.beginPath();ctx.ellipse(0,0,19,32,0,0,7);ctx.fill();for(let i=0;i<5;i++){ctx.strokeStyle='#a73f3b';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(Math.sin(i*3)*15,28);ctx.quadraticCurveTo(Math.cos(i*5)*22,48+i%2*8,Math.sin(i*7)*35,52+i%3*8);ctx.stroke()}ctx.fillStyle='#df8b77';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText(player.relay===3?'EXIT — MOVE':'GATE · LOCKED',0,62);ctx.restore()}
function drawMonster(){let x=monster.x,y=monster.y;ctx.save();ctx.translate(x,y);ctx.shadowBlur=monster.alert?25:10;ctx.shadowColor='#ad2724';ctx.fillStyle='#160d0e';ctx.beginPath();ctx.ellipse(0,4,14,20,0,0,7);ctx.fill();ctx.strokeStyle='#301517';ctx.lineWidth=7;for(let s of [-1,1]){ctx.beginPath();ctx.moveTo(s*5,12);ctx.lineTo(s*11,25);ctx.lineTo(s*15,31);ctx.stroke();ctx.beginPath();ctx.moveTo(s*6,-2);ctx.lineTo(s*15,2);ctx.lineTo(s*19,10);ctx.stroke()}ctx.fillStyle='#831f20';ctx.beginPath();ctx.arc(0,-14,11,0,7);ctx.fill();ctx.fillStyle='#ce4940';ctx.fillRect(-6,-18,3,2);ctx.fillRect(3,-18,3,2);if(monster.alert>.55){ctx.strokeStyle='#ee5750';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,25+Math.sin(monster.phase)*3,0,7);ctx.stroke()}ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.fillStyle='#080a09';ctx.beginPath();ctx.ellipse(0,10,13,6,0,0,7);ctx.fill();if(player.invuln>0&&Math.floor(player.invuln*12)%2)ctx.globalAlpha=.4;ctx.fillStyle='#c7b998';ctx.beginPath();ctx.arc(0,-8,7,0,7);ctx.fill();ctx.fillStyle='#9b4339';ctx.fillRect(-9,-2,18,14);ctx.fillStyle='#4b4c42';ctx.fillRect(-8,10,6,7);ctx.fillRect(2,10,6,7);ctx.strokeStyle='#ded1a6';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(player.fx*7,0);ctx.lineTo(player.fx*15,-2+player.fy*5);ctx.stroke();ctx.restore()}
function drawDarkness(){if(!started)return;ctx.save();ctx.fillStyle='rgba(3,6,8,.78)';ctx.fillRect(0,0,canvas.width,canvas.height);if(player.light){let px=player.x-camera.x,py=player.y-camera.y;let g=ctx.createRadialGradient(px,py,22,px,py,245);g.addColorStop(0,'rgba(0,0,0,.98)');g.addColorStop(.52,'rgba(0,0,0,.8)');g.addColorStop(1,'rgba(0,0,0,0)');ctx.globalCompositeOperation='destination-out';ctx.fillStyle=g;ctx.beginPath();ctx.arc(px,py,245,0,7);ctx.fill();ctx.globalCompositeOperation='source-over';ctx.fillStyle='rgba(222,187,115,.07)';ctx.beginPath();ctx.arc(px,py,70,0,7);ctx.fill()}else{let px=player.x-camera.x,py=player.y-camera.y;ctx.globalCompositeOperation='destination-out';let g=ctx.createRadialGradient(px,py,0,px,py,100);g.addColorStop(0,'rgba(0,0,0,.65)');g.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=g;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.globalCompositeOperation='source-over'}ctx.restore()}
function drawScreenUI(){if(!started)return;ctx.save();ctx.font='11px monospace';ctx.textAlign='left';ctx.fillStyle='rgba(232,222,199,.8)';ctx.fillText('NIGHT SHIFT  /  '+fmt(elapsed),18,25);ctx.textAlign='right';ctx.fillStyle=monster.alert>.5?'#ef6459':'rgba(220,215,200,.55)';ctx.fillText(monster.alert>.5?'MOVEMENT NEARBY':'FIELD FREQUENCY: 87.6',canvas.width-18,25);if(toastTime>0){ctx.globalAlpha=Math.min(1,toastTime*2);ctx.textAlign='center';ctx.fillStyle='rgba(8,10,10,.8)';ctx.fillRect(canvas.width/2-160,canvas.height-59,320,31);ctx.fillStyle='#e6d9bb';ctx.font='11px monospace';ctx.fillText(toast,canvas.width/2,canvas.height-39)}ctx.restore()}
function frame(now){let dt=Math.min(.034,(now-last)/1000||0);last=now;update(dt);draw()}

document.getElementById('start').addEventListener('click',reset);
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if(k==='f'&&!e.repeat&&started&&!ended){player.light=!player.light;document.getElementById('lightState').textContent=player.light?'ON':'OFF';showToast(player.light?'FLASHLIGHT ON':'FLASHLIGHT OFF')}if(k==='r'&&!e.repeat)reset()});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
document.querySelectorAll('.mobile-controls button').forEach(button=>{const key=button.dataset.key.toLowerCase();button.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(key);button.setPointerCapture(e.pointerId)});button.addEventListener('pointerup',e=>{e.preventDefault();keys.delete(key)});button.addEventListener('pointercancel',()=>keys.delete(key));if(key==='f')button.addEventListener('click',()=>{if(started&&!ended){player.light=!player.light;document.getElementById('lightState').textContent=player.light?'ON':'OFF';showToast(player.light?'FLASHLIGHT ON':'FLASHLIGHT OFF')}})});
updateUI();camera.x=0;camera.y=0;draw();
</script>
</body>
</html>

