function drawGate(){let x=exit.x,y=exit.y,p=.5+.5*Math.sin(elapsed*2.7);ctx.save();ctx.translate(x,y);ctx.globalAlpha=.16+p*.12;ctx.fillStyle='#dd4c46';ctx.beginPath();ctx.arc(0,0,66+p*10,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#a63b37';ctx.lineWidth=7;ctx.beginPath();ctx.ellipse(0,0,29,43,0,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#d6584e';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,23,37,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#080b0c';ctx.beginPath();ctx.ellipse(0,0,19,32,0,0,Math.PI*2);ctx.fill();for(let i=0;i<5;i++){ctx.strokeStyle='#a73f3b';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(Math.sin(i*3)*15,28);ctx.quadraticCurveTo(Math.cos(i*5)*22,48+i%2*8,Math.sin(i*7)*35,52+i%3*8);ctx.stroke()}ctx.fillStyle='#df8b77';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText(player.relay===3?'EXIT — MOVE':'GATE · LOCKED',0,62);ctx.restore()}
